// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address actor, address recipient) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(recipient != address(c));
        amount = bound(amount, 1, 1e30);
        vm.deal(actor, amount);
        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(actor);
        try c.multiplicate{value: amount}(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: any successful multiplicate call drains the contract completely;
        // a failed/reverted call is exempt. The mutant succeeds yet keeps the funds.
        assertTrue(!ok || address(c).balance == 0);
    }
}
